import itertools

n = 21
S = {2, 3, 4, 8, 9, 10}

# Build adjacency matrix: True = red (edge in S), False = blue (edge not in S)
adj = [[False]*n for _ in range(n)]
for i in range(n):
    for j in range(i+1, n):
        diff = (j - i) % n
        if diff in S or (n - diff) in S:
            adj[i][j] = adj[j][i] = True

# Check all 5-sets
found_mono = False
for clique in itertools.combinations(range(n), 5):
    all_red = True
    all_blue = True
    for idx, u in enumerate(clique):
        for v in clique[idx+1:]:
            if adj[u][v]:
                all_blue = False
            else:
                all_red = False
            if not all_red and not all_blue:
                break
        if not all_red and not all_blue:
            break
    if all_red:
        print(f"Found red K_5: {clique}")
        found_mono = True
        break
    if all_blue:
        print(f"Found blue K_5: {clique}")
        found_mono = True
        break

if not found_mono:
    print("No monochromatic K_5 found! Solution is valid.")
else:
    print("Solution invalid.")

